INSERT INTO "public"."site_content" ("id", "content", "updated_at") VALUES ('about', '{"sections":[{"id":"hero","type":"hero","title":"About Instrak Venture Capital","styles":{"bgColor":"#1A365D","cardStyle":"glass","textAlign":"left","textColor":"#ffffff","titleColor":"#ffffff","contentAlign":"center","subtitleAlign":"center","itemTitleColor":"#ffffff"},"subtitle":"A global asset and capital management institution specializing in disciplined portfolio mandates, cross-border wealth structuring, and institutional capital strategies."},{"id":"identity","type":"custom","items":[],"title":"Our Identity","styles":{"bgColor":"#00204d","boxWidth":"full","cardColor":"#000729","cardStyle":"glass","textAlign":"center","textColor":"#ffffff","layoutType":"standard","titleColor":"#ffffff","itemTitleColor":"#ffffff"},"content":"Instrak Venture Capital Berhad (IVC) is a global asset and capital management institution specializing in disciplined portfolio mandates, cross-border wealth structuring, and institutional capital strategies.\\nOperating across Asia, the Middle East, Europe, and the United States, IVC serves a select group of institutional investors, corporations, family offices, and ultra-high-net-worth individuals.\\nWe do not operate as a retail investment platform.\\nWe operate as a mandate-driven capital institution."},{"id":"mission","type":"mission","title":"Our institutional Mandate","styles":{"bgColor":"#001738","cardColor":"#000000","textAlign":"left","textColor":"#ffffff","titleColor":"#ffffff","titleFontSize":31,"itemTitleColor":"#ffffff","contentFontSize":17,"subtitleFontSize":18},"values":[{"id":"val-1","icon":"ShieldCheck","text":"Every mandate is structured under defined legal, financial, and risk oversight frameworks.","title":"Governance"},{"id":"val-2","icon":"Eye","text":"Investors receive clear reporting, structured fee models, and visibility into portfolio allocation.","title":"Transparency"},{"id":"val-3","icon":"Scale","text":"We accept engagements selectively, prioritizing long-term institutional relationships over short-term transactions.","title":"Integrity"}],"visionText":"To become a globally respected asset and capital management institution bridging strategic financial corridors between Asia, the Middle East, and major global markets.","missionText":"To structure, protect, and grow global capital through disciplined asset management, transparent governance, and long-term institutional relationships.","visionTitle":"Our Vision","mandateLabel":"","missionTitle":"Our Mission"},{"id":"philosophy","type":"custom","items":[{"id":"phil-1","icon":"Shield","title":"Governance","description":"Every mandate is structured under defined legal, financial, and risk oversight frameworks."},{"id":"phil-2","icon":"Eye","title":"Transparency","description":"Investors receive clear reporting, structured fee models, and visibility into portfolio allocation."},{"id":"phil-3","icon":"Scale","title":"Integrity","description":"We accept engagements selectively, prioritizing long-term institutional relationships over short-term transactions."}],"title":"Our Philosophy","styles":{"bgColor":"#00204d","cardColor":"#000729","textAlign":"center","textColor":"#ffffff","layoutType":"cards","titleColor":"#ffffff","itemTitleColor":"#ffffff"},"subtitle":"At IVC, capital is not treated as a speculative instrument. It is treated as a long-term responsibility."},{"id":"operating-model","type":"custom","items":[{"id":"op-1","icon":"CheckCircle","title":"Evaluated internally"},{"id":"op-2","icon":"CheckCircle","title":"Structurally designed"},{"id":"op-3","icon":"CheckCircle","title":"Risk-assessed"},{"id":"op-4","icon":"CheckCircle","title":"Legally documented"},{"id":"op-5","icon":"CheckCircle","title":"Monitored through institutional reporting protocols"}],"title":"Our Operating Model","styles":{"bgColor":"#001738","cardColor":"#000000","textAlign":"center","textColor":"#ffffff","groupTitle":"OPERATIONAL PROTOCOLS","layoutType":"boxed-group","titleColor":"#ffffff","itemTitleColor":"#ffffff"},"content":"This approach ensures discipline, confidentiality, and long-term capital alignment.","subtitle":"IVC functions through a mandate-based engagement structure. Each client relationship is:"},{"id":"capital-corridor","type":"custom","items":[{"id":"cap-1","icon":"Globe","title":"Asia","description":"Regional growth hub"},{"id":"cap-2","icon":"Globe","title":"Middle East","description":"Strategic capital hub"},{"id":"cap-3","icon":"Globe","title":"Europe","description":"Institutional investment hub"},{"id":"cap-4","icon":"Globe","title":"United States","description":"Global financial hub"}],"title":"Our Global Capital Corridor","styles":{"bgColor":"#00204d","cardColor":"#000729","textAlign":"center","textColor":"#ffffff","layoutType":"grid","titleColor":"#ffffff","itemTitleColor":"#ffffff"},"subtitle":"IVC specializes in cross-border capital structuring across key financial regions:"},{"id":"who-we-serve","type":"custom","items":[{"id":"serve-1","icon":"Building2","title":"Institutional investors"},{"id":"serve-2","icon":"Users","title":"Family offices"},{"id":"serve-3","icon":"Briefcase","title":"Publicly listed corporations"},{"id":"serve-4","icon":"Target","title":"Strategic investment groups"},{"id":"serve-5","icon":"UserCheck","title":"Ultra-high-net-worth individuals"},{"id":"serve-6","icon":"Shield","title":"Sovereign-linked entities"}],"title":"Who We Serve","styles":{"bgColor":"#001738","cardColor":"#000000","textAlign":"center","textColor":"#ffffff","layoutType":"icon-group","titleColor":"#ffffff","itemTitleColor":"#ffffff"},"subtitle":"IVC works with a select group of global clients. Engagement is subject to internal governance review."},{"id":"core-pillars","type":"custom","items":[{"id":"pillar-1","icon":"Briefcase","title":"Asset Management","description":"Institutional portfolio mandates focused on capital preservation, structured yield, and alternative asset allocation."},{"id":"pillar-2","icon":"Users","title":"Private Wealth & Family Office","description":"Cross-border wealth structuring for ultra-high-net-worth individuals and multi-generational families."},{"id":"pillar-3","icon":"Building2","title":"Institutional Capital Solutions","description":"Structured financing and capital market strategies supporting corporate growth and asset-backed investments."}],"title":"Core Business Pillars","styles":{"bgColor":"#00204d","cardColor":"#000729","textAlign":"center","textColor":"#ffffff","layoutType":"cards","titleColor":"#ffffff","itemTitleColor":"#ffffff"}},{"id":"governance-framework","type":"custom","items":[{"id":"gov-1","icon":"Shield","title":"Risk Oversight","description":"Structured portfolio allocation models, exposure limits, counterparty evaluation, periodic mandate review."},{"id":"gov-2","icon":"FileText","title":"Legal Structuring","description":"Institutional-grade documentation, cross-border compliance alignment, mandate-based engagement protocols."},{"id":"gov-3","icon":"Eye","title":"Reporting Discipline","description":"Periodic portfolio reporting, asset allocation transparency, risk exposure summaries."}],"title":"Our Governance Framework","styles":{"bgColor":"#001738","cardColor":"#000000","textAlign":"center","textColor":"#ffffff","layoutType":"grid","titleColor":"#ffffff","itemTitleColor":"#ffffff"},"subtitle":"IVC operates under institutional-grade governance principles."},{"id":"leadership-message","type":"custom","items":[],"title":"Leadership Message","styles":{"bgColor":"#00204d","cardColor":"#000729","textAlign":"center","textColor":"#FFFFFF","layoutType":"dialog","titleColor":"#ffffff","itemTitleColor":"#ffffff"},"content":"Instrak Venture Capital Berhad was established with a singular objective: to build a disciplined capital institution that bridges strategic financial corridors across the world.\\nIn a global environment where capital often moves faster than governance, we believe discipline, transparency, and integrity are the true foundations of sustainable wealth.\\nOur approach is simple: We do not chase transactions.\\nWe structure mandates.\\nWe build long-term capital partnerships.","subtitle":"From the Office of the Group CEO","dialogName":"KAHAR KAMARUDIN, ANS","dialogRole":"GROUP CHIEF EXECUTIVE OFFICER (GCEO)","dialogImage":"https://osxqnhwlxhspczudglyl.supabase.co/storage/v1/object/public/site-assets/dialog/1771478005828-eyogg2.webp"},{"id":"institutional-conduct","type":"custom","items":[{"id":"conduct-1","icon":"Shield","title":"Confidential"},{"id":"conduct-2","icon":"ShieldCheck","title":"Governance-reviewed"},{"id":"conduct-3","icon":"Target","title":"Structurally designed"},{"id":"conduct-4","icon":"FileText","title":"Institutionally documented"}],"title":"Institutional Conduct","styles":{"bgColor":"#001738","cardColor":"#000000","textAlign":"center","textColor":"#ffffff","layoutType":"list","titleColor":"#ffffff","itemTitleColor":"#ffffff","contentPosition":"header"},"content":"Each engagement is:","subtitle":"IVC maintains a selective engagement policy. We do not operate on transaction volume. We operate on mandate integrity."},{"id":"board","type":"board","title":"Board of Directors","styles":{"bgColor":"#00204d","cardColor":"#000729","textAlign":"left","textColor":"#ffffff","titleColor":"#ffffff","subtitleAlign":"left","itemTitleColor":"#ffffff","subtitleFontSize":17},"subtitle":"Guided by seasoned leaders with a commitment to integrity, compliance, and industrial excellence.","sectionLabel":""},{"id":"partners","type":"partners","title":"Strategic Partner","styles":{"bgColor":"#001738","cardColor":"#000000","textAlign":"left","textColor":"#ffffff","titleColor":"#ffffff","itemTitleColor":"#ffffff"}},{"id":"milestone","type":"milestone","title":"Investment Milestone","styles":{"bgColor":"#000729","cardColor":"#000729","textAlign":"left","textColor":"#ffffff","titleColor":"#ffffff","itemTitleColor":"#ffffff"}},{"id":"closing","type":"custom","items":[],"title":"Closing Statement","styles":{"bgColor":"#001738","cardColor":"#000000","textAlign":"center","textColor":"#FFFFFF","layoutType":"standard","titleColor":"#ffffff","itemTitleColor":"#ffffff"},"content":"IVC exists to serve capital with responsibility.\\nWe structure wealth with discipline.\\nWe govern capital with transparency.\\nWe grow institutions with integrity."}]}', '2026-02-19 12:39:10.674+00'), ('board', '{"directors":[{"id":"dir-1","name":"KAHAR KAMARUDIN, ANS","role":"GROUP CHIEF EXECUTIVE OFFICER (GCEO)","image":"https://osxqnhwlxhspczudglyl.supabase.co/storage/v1/object/public/site-assets/directors/1771478586781-o8nlc0.webp"},{"id":"dir-2","name":"PROF IR. DR. NORIDAH","role":"NON-EXECUTIVE DIRECTOR","image":"https://osxqnhwlxhspczudglyl.supabase.co/storage/v1/object/public/site-assets/directors/1771479054297-0o73um.webp"},{"id":"dir-3","name":"RAFI YA''ACOB","role":"CHIEF OPERATING OFFICER (COO)","image":"https://osxqnhwlxhspczudglyl.supabase.co/storage/v1/object/public/site-assets/directors/1771479095113-fzv359.webp"},{"id":"dir-4","name":"ZALIZA YAHYA, CPA","role":"CHIEF FINANCIAL OFFICER (CFO)","image":"https://osxqnhwlxhspczudglyl.supabase.co/storage/v1/object/public/site-assets/directors/1771479108886-6414ez.webp"},{"id":"dir-5","name":"NORZALIZA ABD GHAFAR","role":"GENERAL MANAGER","image":"https://osxqnhwlxhspczudglyl.supabase.co/storage/v1/object/public/site-assets/directors/1771479130026-aeb9lv.webp"},{"id":"dir-6","name":"NORLI HIDAYATUL AINI","role":"GENERAL MANAGER","image":"https://osxqnhwlxhspczudglyl.supabase.co/storage/v1/object/public/site-assets/directors/1771479178376-4yg5jp.webp"},{"id":"dir-7","name":"DR. SUHAILY SHAHIMI","role":"INTERNAL AUDITOR","image":"https://osxqnhwlxhspczudglyl.supabase.co/storage/v1/object/public/site-assets/directors/1771479178398-0xp5ne.webp"}],"styleColors":{"bioColor":"#ffffff","nameColor":"#ffffff","roleColor":"#ffffff"}}', '2026-02-19 12:39:10.675+00'), ('career', '{"jobs":[{"id":1771433591395,"type":"Cont